SELECT COUNT(*) AS user_cnt FROM (
  SELECT o.user_id FROM payments p JOIN orders o ON o.id = p.order_id WHERE p.method = '微信'
  INTERSECT
  SELECT o.user_id FROM orders o JOIN order_items oi ON oi.order_id = o.id JOIN products pr ON pr.id = oi.product_id WHERE pr.category = '图书'
) t;

